import assert from 'node:assert/strict';
import {readFileSync,mkdirSync,writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {chromium,webkit} from 'playwright';
import {recordingForWord} from '../lib/word-listening.ts';
const folder='docs/writing-forms-20261102/',out=process.env.KLINK_TEST_OUTPUT||folder+'local',base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:19031';mkdirSync(out,{recursive:true});
const review=JSON.parse(readFileSync(folder+'word-audio-review.json')),instruction=JSON.parse(readFileSync(folder+'audio-review.json')).selectedInstruction,sha=b=>createHash('sha256').update(b).digest('hex'),files=[],native=[],errors=[];
const baseline=JSON.parse(execFileSync('git',['show',JSON.parse(readFileSync(folder+'import-manifest.json')).baselineSourceCommit+':data/klink-word-listening.json'],{maxBuffer:32e6})),current=JSON.parse(readFileSync('data/klink-word-listening.json'));
for(const[word,recordings]of Object.entries(baseline))assert.deepEqual(current[word],recordings,word+': preserve every prior candidate and default');
try{
 for(const bundle of review.bundles){const response=await fetch(base+bundle.src);assert.equal(response.status,200);const bytes=Buffer.from(await response.arrayBuffer());assert.equal(bytes.length,bundle.bytes);assert.equal(sha(bytes),bundle.sha256);files.push({kind:'bundle',src:bundle.src,bytes:bytes.length,sha256:sha(bytes),fullFileReadback:true});}
 for(const item of review.selected){assert.deepEqual(recordingForWord(item.word),item.source);const {src,offset,length}=item.source,response=await fetch(base+src,{headers:{Range:`bytes=${offset}-${offset+length-1}`}});assert([200,206].includes(response.status));let body=Buffer.from(await response.arrayBuffer());if(response.status===206)assert.equal(response.headers.get('content-range'),`bytes ${offset}-${offset+length-1}/${review.bundles.find(x=>x.src===src).bytes}`);else body=body.subarray(offset,offset+length);assert.equal(body.length,length);assert.equal(sha(body),item.record.sha256);assert(body.equals(readFileSync(item.record.final)));const pcm=execFileSync('ffmpeg',['-v','error','-i',item.record.final,'-f','s16le','-acodec','pcm_s16le','-']);assert.equal(sha(pcm),item.record.pcmSha256);const tags=JSON.parse(execFileSync('ffprobe',['-v','error','-show_entries','format_tags','-of','json',item.record.final])).format.tags;for(const key of['artist','album_artist','publisher'])assert.equal(tags[key],'Taalroute');assert(!/suno|elevenlabs|generator|encoder/i.test(JSON.stringify(tags)));files.push({kind:'word',word:item.word,src,offset,length,status:response.status,sha256:sha(body),pcmSha256:sha(pcm),embeddedTaalrouteMetadata:true,originalAudioDataPreserved:true});}
 {const response=await fetch(base+instruction.src);assert.equal(response.status,200);const bytes=Buffer.from(await response.arrayBuffer());assert.equal(sha(bytes),instruction.sha256);assert(bytes.equals(readFileSync(instruction.final)));files.push({kind:'instruction',src:instruction.src,sha256:sha(bytes),fullFileReadback:true,embeddedTaalrouteMetadata:true});}
 const clips=review.selected.map(x=>({word:x.word,...x.source,sha256:x.record.sha256}));
 for(const[engine,type]of Object.entries({chromium,webkit})){
  const browser=await type.launch({headless:true,...(engine==='chromium'?{channel:'chrome'}:{})});try{
   const page=await browser.newPage();page.on('pageerror',e=>errors.push({engine,message:e.message}));await page.goto(base);
   for(const clip of clips)for(const mode of['range','full-response']){
    const decoded=await page.evaluate(async({clip,mode})=>{const end=clip.offset+clip.length-1,response=await fetch(clip.src,mode==='range'?{headers:{Range:`bytes=${clip.offset}-${end}`}}:{});if(![200,206].includes(response.status))throw Error('Unexpected audio status');const body=await response.arrayBuffer(),bytes=response.status===200?body.slice(clip.offset,end+1):body;if(bytes.byteLength!==clip.length)throw Error('Truncated clip');const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');const blob=URL.createObjectURL(new Blob([bytes],{type:'audio/wav'})),audio=new Audio();try{const duration=await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Native decode timeout')),10000);audio.onloadedmetadata=()=>{clearTimeout(timeout);resolve(audio.duration);};audio.onerror=()=>{clearTimeout(timeout);reject(Error('Native WAV decoding failed'));};audio.src=blob;audio.load();});if(!(duration>0&&Number.isFinite(duration)))throw Error('Invalid duration');return{word:clip.word,mode,status:response.status,sha256:hash,duration,native:audio instanceof HTMLAudioElement};}finally{audio.pause();audio.removeAttribute('src');audio.load();URL.revokeObjectURL(blob);}}, {clip,mode});assert.equal(decoded.sha256,clip.sha256);assert(decoded.native&&decoded.duration>0);native.push({engine,...decoded});
   }await page.close();
  }finally{await browser.close();}
 }
}finally{writeFileSync(out+'/media.json',JSON.stringify({base,priorWordModelsAndDefaultsPreserved:true,files,native,errors,requestsMocked:false,humanListeningPerformed:false,properNamePronunciationReviewOpen:review.selected.filter(x=>x.basis==='bounded-proper-name-inference').map(x=>x.word)},null,2)+'\n');}
assert.equal(files.filter(x=>x.kind==='word').length,76);assert.equal(native.length,304);assert.deepEqual(errors,[]);console.log('Passed7 complete bundles,76 exact word ranges,one instruction and304 real native WAV decodes across ranged/full responses; all prior wordaudio defaults preserved.');
